"""The shelves: catalogue, stock movements and stock levels."""

import re
from dataclasses import dataclass
from decimal import Decimal

from ._lines import ParseError, content_lines, is_sku, parse_date

TAX_RATES = {
    "standard": Decimal("0.20"),
    "reduced": Decimal("0.05"),
    "zero": Decimal("0"),
}

_PRICE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
_COUNT_RE = re.compile(r"[0-9]+")
_QTY_RE = re.compile(r"[+-]?[0-9]+")
_MOVE_RE = re.compile(r"([^ \t]+)[ \t]+([^ \t]+)[ \t]+([^ \t]+)(?:[ \t]+(.*))?", re.DOTALL)


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str = "standard"

    @property
    def tax_rate(self):
        return TAX_RATES[self.tax]


@dataclass(frozen=True)
class Movement:
    date: "datetime.date"  # noqa: F821
    sku: str
    quantity: int
    note: str = ""


def parse_catalog(text):
    """Parse ``catalog.txt`` text into a dict of SKU -> Product."""
    catalog = {}
    for number, line in content_lines(text):
        fields = [f.strip() for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        sku, name, price, reorder = fields[:4]
        if not is_sku(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "empty product name")
        if not _PRICE_RE.fullmatch(price):
            raise ParseError(number, "bad price %r" % price)
        price_value = Decimal(price).quantize(Decimal("0.01"))
        if price_value < Decimal("0.01"):
            raise ParseError(number, "price must be at least 0.01")
        if not _COUNT_RE.fullmatch(reorder):
            raise ParseError(number, "bad reorder level %r" % reorder)
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(number, "bad tax band %r (standard, reduced or zero)" % fields[4])
        catalog[sku] = Product(sku, name, price_value, int(reorder), tax)
    return catalog


def counting_order(movements):
    """Return the movements in the order they count: by date, file order within a day."""
    return [m for _, m in sorted(enumerate(movements), key=lambda p: (p[1].date, p[0]))]


def first_negative(movements):
    """Index (into ``movements``) of the first movement that takes stock below zero, or None."""
    balance = {}
    for index, move in sorted(enumerate(movements), key=lambda p: (p[1].date, p[0])):
        balance[move.sku] = balance.get(move.sku, 0) + move.quantity
        if balance[move.sku] < 0:
            return index
    return None


def parse_movements(text, catalog):
    """Parse ``movements.txt`` text into a list of Movement, in file order."""
    moves = []
    numbers = []
    for number, line in content_lines(text):
        match = _MOVE_RE.fullmatch(line)
        if not match:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date_s, sku, qty_s, note = match.groups()
        date = parse_date(date_s)
        if date is None:
            raise ParseError(number, "bad date %r" % date_s)
        if not is_sku(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku not in catalog:
            raise ParseError(number, "SKU %s is not in the catalogue" % sku)
        if not _QTY_RE.fullmatch(qty_s) or int(qty_s) == 0:
            raise ParseError(number, "bad quantity %r (a non-zero whole number)" % qty_s)
        moves.append(Movement(date, sku, int(qty_s), (note or "").strip()))
        numbers.append(number)
    bad = first_negative(moves)
    if bad is not None:
        raise ParseError(numbers[bad], "stock of %s would go below zero" % moves[bad].sku)
    return moves


def stock_levels(catalog, movements):
    """Dict of SKU -> quantity on the shelf for every product in the catalogue."""
    levels = {sku: 0 for sku in catalog}
    for move in movements:
        levels[move.sku] = levels.get(move.sku, 0) + move.quantity
    return levels


def stock_status(onhand, reorder):
    if onhand <= 0:
        return "out"
    if onhand <= reorder:
        return "low"
    return "ok"


def buy_quantity(onhand, reorder):
    return max(1, 2 * reorder - onhand)


def history(sku, movements):
    """List of ``(movement, balance_after)`` for one SKU, in counting order."""
    balance = 0
    rows = []
    for move in counting_order(movements):
        if move.sku == sku:
            balance += move.quantity
            rows.append((move, balance))
    return rows


def available_on(sku, movements, date):
    """How many of ``sku`` can leave the shelf on ``date`` without breaking any later movement."""
    balance = 0
    at_date = None
    lowest_later = None
    for move in counting_order(movements):
        if move.sku != sku:
            continue
        if move.date > date and at_date is None:
            at_date = balance
        balance += move.quantity
        if move.date > date:
            lowest_later = balance if lowest_later is None else min(lowest_later, balance)
    if at_date is None:
        at_date = balance
    limit = at_date if lowest_later is None else min(at_date, lowest_later)
    return max(0, limit)


def format_delta(quantity):
    return "%+d" % quantity
EOF

