            "invoiced": str(invoice.total) if invoice else "0.00",
        })
    if fmt == "json":
        return dumps(rows)
    if fmt == "csv":
        buffer = io.StringIO()
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
