def _error(message):
    try:
        sys.stderr.write("stockroom: %s\n" % message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def _write_stdout(text):
    try:
        out = sys.stdout.buffer
    except AttributeError:  # replaced by a text-only stream (e.g. in tests)
        sys.stdout.write(text)
        sys.stdout.flush()
        return
    sys.stdout.flush()
    out.write(text.encode("utf-8"))
    out.flush()


def run(argv):
    try:
        directory, command, args, opts = parse_command_line(argv)
    except UsageError as exc:
        _error(str(exc))
        try:
            sys.stderr.write(USAGE)
        except (OSError, ValueError):
            pass
        return 2
    try:
        data = Data(directory, FILES[command])
        output = HANDLERS[command](data, args, opts)
    except ReadError as exc:
        _error(str(exc))
        return 2
    except Refused as exc:
        _error(str(exc))
        return 1
    try:
        _write_stdout(output)
    except BrokenPipeError:
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except (OSError, ValueError, AttributeError):
            pass
    return 0


def main(argv=None):
    return run(sys.argv[1:] if argv is None else list(argv))


if __name__ == "__main__":
    sys.exit(main())
