class UsageError(Exception):
    """Something is wrong with the command line (exit 2)."""


class ReadError(Exception):
    """A file cannot be read (exit 2)."""


class Refused(Exception):
    """A data mistake or a refused request (exit 1)."""


# ---------------------------------------------------------------- command line

def parse_command_line(argv):
    directory = "."
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a folder")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
            continue
        rest.append(arg)
        i += 1
    if directory == "":
        raise UsageError("--dir needs a folder")
    if not rest:
        raise UsageError("no command given")
    command, args = rest[0], rest[1:]
    if command not in COMMANDS:
        if command.startswith("-"):
            raise UsageError("unknown option %s" % command)
        raise UsageError("unknown command %r" % command)
    low, high, allowed = COMMANDS[command]
    options = {}
    positionals = []
    if allowed is None:
        positionals = args
    else:
        i = 0
        while i < len(args):
            arg = args[i]
            if arg.startswith("-") and arg != "-":
                name, eq, value = arg.partition("=")
                if name not in allowed:
                    raise UsageError("unknown option %s" % name)
                if name == "--format":
                    if not eq:
                        if i + 1 >= len(args):
                            raise UsageError("--format needs a value")
                        i += 1
                        value = args[i]
                    if value not in ("text", "csv", "json"):
                        raise UsageError("bad --format %r (text, csv or json)" % value)
                    options["format"] = value
                else:
                    if eq:
                        raise UsageError("%s takes no value" % name)
                    options[name.lstrip("-")] = True
            else:
                positionals.append(arg)
            i += 1
    if not low <= len(positionals) <= high:
        raise UsageError("wrong number of arguments for %s" % command)
    if command in ("receive", "ship", "fulfil"):
        date_arg = positionals[0] if command != "fulfil" else positionals[1]
        if parse_date(date_arg) is None:
            raise UsageError("bad date %r (YYYY-MM-DD)" % date_arg)
    return directory, command, positionals, options


# ---------------------------------------------------------------- files

def read_text(directory, name, required):
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise ReadError("%s: file not found" % name)
        return ""
    except OSError as exc:
        raise ReadError("%s: cannot read: %s" % (name, exc.strerror or exc))
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise ReadError("%s: not valid UTF-8" % name)
    return text[1:] if text.startswith("\ufeff") else text


class Data:
    def __init__(self, directory, names):
        if not os.path.isdir(directory):
            raise ReadError("%s: no such folder" % directory)
        self.directory = directory
        texts = {name: read_text(directory, name, name == CATALOG) for name in names}
        self.catalog = self._parse(CATALOG, parse_catalog, texts[CATALOG])
        self.movements = None
        self.orders = None
        if MOVEMENTS in texts:
            self.movements = self._parse(MOVEMENTS, parse_movements, texts[MOVEMENTS], self.catalog)
        if ORDERS in texts:
            self.orders = self._parse(ORDERS, parse_orders, texts[ORDERS], self.catalog)

    @staticmethod
    def _parse(name, func, *args):
        try:
            return func(*args)
        except ParseError as exc:
            raise Refused("%s: %s" % (name, exc))

    def find_order(self, order_id):
        wanted = order_id.upper()
        for order in self.orders:
            if order.id == wanted:
                return order
        raise Refused("order %s is not in %s" % (order_id, ORDERS))

    def append_movements(self, lines):
        path = os.path.join(self.directory, MOVEMENTS)
        try:
            with open(path, "ab+") as handle:
                handle.seek(0, os.SEEK_END)
                prefix = b""
                if handle.tell() > 0:
                    handle.seek(-1, os.SEEK_END)
                    if handle.read(1) != b"\n":
                        prefix = b"\n"
                handle.seek(0, os.SEEK_END)
                handle.write(prefix + "".join(line + "\n" for line in lines).encode("utf-8"))
        except OSError as exc:
            raise ReadError("%s: cannot write: %s" % (MOVEMENTS, exc.strerror or exc))


