"""The ``stockroom`` command."""

import csv
import io
import json
import os
import sys

from ._lines import ParseError, parse_date
from .orders import (invoice_order, order_number, order_status, parse_orders, price_order,
                     shipment_note, shipped_quantities)
from .shelves import (Movement, buy_quantity, first_negative, format_delta, history,
                      parse_catalog, parse_movements, stock_levels, stock_status, available_on)

USAGE = """usage: stockroom [--dir DIR] COMMAND [ARGS]

commands:
  stock [--json]
  low [--json]
  history SKU [--json]
  receive DATE SKU QUANTITY [NOTE]
  ship DATE SKU QUANTITY [NOTE]
  quote ORDER [--json]
  fulfil ORDER DATE
  invoice ORDER [--json]
  report [--format text|csv|json]
"""

CATALOG = "catalog.txt"
MOVEMENTS = "movements.txt"
ORDERS = "orders.txt"

# command -> (minimum positionals, maximum positionals, allowed options, takes options at all)
COMMANDS = {
    "stock": (0, 0, {"--json"}),
    "low": (0, 0, {"--json"}),
    "history": (1, 1, {"--json"}),
    "receive": (3, 4, None),
    "ship": (3, 4, None),
    "quote": (1, 1, {"--json"}),
    "fulfil": (2, 2, None),
    "invoice": (1, 1, {"--json"}),
    "report": (0, 0, {"--format"}),
}

FILES = {
    "stock": (CATALOG, MOVEMENTS),
    "low": (CATALOG, MOVEMENTS),
    "history": (CATALOG, MOVEMENTS),
    "receive": (CATALOG, MOVEMENTS),
    "ship": (CATALOG, MOVEMENTS),
    "quote": (CATALOG, ORDERS),
    "fulfil": (CATALOG, MOVEMENTS, ORDERS),
    "invoice": (CATALOG, MOVEMENTS, ORDERS),
    "report": (CATALOG, MOVEMENTS, ORDERS),
}


class UsageError(Exception):
    """Something is wrong with the command line (exit 2)."""


class ReadError(Exception):
    """A file cannot be read (exit 2)."""


class Refused(Exception):
    """A data mistake or a refused request (exit 1)."""


# ---------------------------------------------------------------- command line

def parse_command_line(argv):
    directory = "."
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise UsageError("--dir needs a folder")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
            i += 1
            continue
        rest.append(arg)
        i += 1
    if directory == "":
        raise UsageError("--dir needs a folder")
    if not rest:
        raise UsageError("no command given")
    command, args = rest[0], rest[1:]
    if command not in COMMANDS:
        if command.startswith("-"):
            raise UsageError("unknown option %s" % command)
        raise UsageError("unknown command %r" % command)
    low, high, allowed = COMMANDS[command]
    options = {}
    positionals = []
    if allowed is None:
        positionals = args
    else:
        i = 0
        while i < len(args):
            arg = args[i]
            if arg.startswith("-") and arg != "-":
                name, eq, value = arg.partition("=")
                if name not in allowed:
                    raise UsageError("unknown option %s" % name)
                if name == "--format":
                    if not eq:
                        if i + 1 >= len(args):
                            raise UsageError("--format needs a value")
                        i += 1
                        value = args[i]
                    if value not in ("text", "csv", "json"):
                        raise UsageError("bad --format %r (text, csv or json)" % value)
                    options["format"] = value
                else:
                    if eq:
                        raise UsageError("%s takes no value" % name)
                    options[name.lstrip("-")] = True
            else:
                positionals.append(arg)
            i += 1
    if not low <= len(positionals) <= high:
        raise UsageError("wrong number of arguments for %s" % command)
    if command in ("receive", "ship", "fulfil"):
        date_arg = positionals[0] if command != "fulfil" else positionals[1]
        if parse_date(date_arg) is None:
            raise UsageError("bad date %r (YYYY-MM-DD)" % date_arg)
    return directory, command, positionals, options


# ---------------------------------------------------------------- files

def read_text(directory, name, required):
    path = os.path.join(directory, name)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise ReadError("%s: file not found" % name)
        return ""
    except OSError as exc:
        raise ReadError("%s: cannot read: %s" % (name, exc.strerror or exc))
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise ReadError("%s: not valid UTF-8" % name)
    return text[1:] if text.startswith("\ufeff") else text


class Data:
    def __init__(self, directory, names):
        if not os.path.isdir(directory):
            raise ReadError("%s: no such folder" % directory)
        self.directory = directory
        texts = {name: read_text(directory, name, name == CATALOG) for name in names}
        self.catalog = self._parse(CATALOG, parse_catalog, texts[CATALOG])
        self.movements = None
        self.orders = None
        if MOVEMENTS in texts:
            self.movements = self._parse(MOVEMENTS, parse_movements, texts[MOVEMENTS], self.catalog)
        if ORDERS in texts:
            self.orders = self._parse(ORDERS, parse_orders, texts[ORDERS], self.catalog)

    @staticmethod
    def _parse(name, func, *args):
        try:
            return func(*args)
        except ParseError as exc:
            raise Refused("%s: %s" % (name, exc))

    def find_order(self, order_id):
        wanted = order_id.upper()
        for order in self.orders:
            if order.id == wanted:
                return order
        raise Refused("order %s is not in %s" % (order_id, ORDERS))

    def append_movements(self, lines):
        path = os.path.join(self.directory, MOVEMENTS)
        try:
            with open(path, "ab+") as handle:
                handle.seek(0, os.SEEK_END)
                prefix = b""
                if handle.tell() > 0:
                    handle.seek(-1, os.SEEK_END)
                    if handle.read(1) != b"\n":
                        prefix = b"\n"
                handle.seek(0, os.SEEK_END)
                handle.write(prefix + "".join(line + "\n" for line in lines).encode("utf-8"))
        except OSError as exc:
            raise ReadError("%s: cannot write: %s" % (MOVEMENTS, exc.strerror or exc))


# ---------------------------------------------------------------- output helpers

def dumps(value):
    return json.dumps(value, indent=2, ensure_ascii=False) + "\n"


def lines_out(rows):
    return "".join(row + "\n" for row in rows)


def movement_line(move):
    text = "%s %s %s" % (move.date.isoformat(), move.sku, format_delta(move.quantity))
    return text + (" " + move.note if move.note else "")


def quote_output(header, order, quote, as_json):
    if as_json:
        return dumps({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [{"sku": l.sku, "quantity": l.quantity, "unit": str(l.unit),
                       "gross": str(l.gross), "discount": str(l.discount), "net": str(l.net)}
                      for l in quote.lines],
            "subtotal": str(quote.subtotal),
            "order_discount": str(quote.order_discount),
            "tax": str(quote.tax),
            "total": str(quote.total),
        })
    rows = [header + "%s %s %s" % (order.id, order.date.isoformat(), order.customer)]
    for l in quote.lines:
        rows.append("%s %d %s %s %s %s" % (l.sku, l.quantity, l.unit, l.gross, l.discount, l.net))
    rows.append("subtotal %s" % quote.subtotal)
    rows.append("order discount %s" % quote.order_discount)
    rows.append("tax %s" % quote.tax)
    rows.append("total %s" % quote.total)
    return lines_out(rows)


# ---------------------------------------------------------------- commands

def cmd_stock(data, args, opts):
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        rows.append({"sku": sku, "name": product.name, "onhand": levels[sku],
                     "status": stock_status(levels[sku], product.reorder)})
    if opts.get("json"):
        return dumps(rows)
    return lines_out("%s %d %s %s" % (r["sku"], r["onhand"], r["status"], r["name"]) for r in rows)


def cmd_low(data, args, opts):
    levels = stock_levels(data.catalog, data.movements)
    rows = []
    for sku in sorted(data.catalog):
        product = data.catalog[sku]
        if stock_status(levels[sku], product.reorder) in ("low", "out"):
            rows.append({"sku": sku, "onhand": levels[sku], "reorder": product.reorder,
                         "buy": buy_quantity(levels[sku], product.reorder)})
    if opts.get("json"):
        return dumps(rows)
    return lines_out("%s %d %d %d" % (r["sku"], r["onhand"], r["reorder"], r["buy"]) for r in rows)


def cmd_history(data, args, opts):
    sku = args[0].upper()
    if sku not in data.catalog:
        raise Refused("SKU %s is not in %s" % (args[0], CATALOG))
    rows = [{"date": m.date.isoformat(), "delta": format_delta(m.quantity), "balance": balance,
             "note": m.note} for m, balance in history(sku, data.movements)]
    if opts.get("json"):
        return dumps(rows)
    return lines_out(" ".join([r["date"], r["delta"], str(r["balance"])] + ([r["note"]] if r["note"] else []))
                     for r in rows)


def _move_command(data, args, sign):
    date = parse_date(args[0])
    sku_arg, qty_arg = args[1], args[2]
    note = args[3] if len(args) > 3 else ""
    sku = sku_arg.upper()
    if sku not in data.catalog:
        raise Refused("SKU %s is not in %s" % (sku_arg, CATALOG))
    if not (qty_arg.isascii() and qty_arg.isdigit()) or int(qty_arg) < 1:
        raise Refused("bad quantity %r (a whole number of one or more, no sign)" % qty_arg)
    if "\n" in note or "\r" in note:
        raise Refused("a note may not contain a line break")
    move = Movement(date, sku, sign * int(qty_arg), note.strip())
    if first_negative(data.movements + [move]) is not None:
        raise Refused("stock of %s would go below zero" % sku)
    line = movement_line(move)
    data.append_movements([line])
    return line + "\n"


def cmd_receive(data, args, opts):
    return _move_command(data, args, +1)


def cmd_ship(data, args, opts):
    return _move_command(data, args, -1)


def cmd_quote(data, args, opts):
    order = data.find_order(args[0])
    return quote_output("", order, price_order(order, data.catalog), opts.get("json"))


def cmd_invoice(data, args, opts):
    order = data.find_order(args[0])
    quote = invoice_order(order, data.catalog, data.movements)
    if quote is None:
        raise Refused("nothing has shipped on order %s yet" % order.id)
    return quote_output("invoice ", order, quote, opts.get("json"))


def cmd_fulfil(data, args, opts):
    order = data.find_order(args[0])
    date = parse_date(args[1])
    if date < order.date:
        raise Refused("%s is before the date of order %s (%s)" % (args[1], order.id, order.date.isoformat()))
    shipped = shipped_quantities(order, data.movements)
    note = shipment_note(order.id)
    new_moves = []
    rows = []
    after = {}
    for sku, quantity in order.lines:
        owed = quantity - shipped[sku]
        send = min(owed, available_on(sku, data.movements, date)) if owed > 0 else 0
        if send > 0:
            new_moves.append(Movement(date, sku, -send, note))
        after[sku] = shipped[sku] + send
        rows.append("%s shipped %d backordered %d" % (sku, send, owed - send))
    rows.append("status %s" % order_status(order, after))
    if new_moves:
        if first_negative(data.movements + new_moves) is not None:  # defensive; cannot happen
            raise Refused("shipment would take stock below zero")
        data.append_movements([movement_line(m) for m in new_moves])
    return lines_out(rows)


def cmd_report(data, args, opts):
    fmt = opts.get("format", "text")
    rows = []
    for order in sorted(data.orders, key=lambda o: (o.date, order_number(o.id))):
        shipped = shipped_quantities(order, data.movements)
        invoice = invoice_order(order, data.catalog, data.movements)
        rows.append({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "status": order_status(order, shipped),
            "ordered": sum(q for _, q in order.lines),
            "shipped": sum(shipped.values()),
            "quoted": str(price_order(order, data.catalog).total),
            "invoiced": str(invoice.total) if invoice else "0.00",
        })
    if fmt == "json":
        return dumps(rows)
    if fmt == "csv":
        buffer = io.StringIO()
        keys = ["order", "date", "customer", "status", "ordered", "shipped", "quoted", "invoiced"]
        writer = csv.DictWriter(buffer, fieldnames=keys, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)
        return buffer.getvalue()
    return lines_out("%s %s %s %s %d/%d %s %s" % (r["order"], r["date"], r["customer"], r["status"],
                                                 r["shipped"], r["ordered"], r["quoted"], r["invoiced"])
                     for r in rows)


HANDLERS = {
    "stock": cmd_stock,
    "low": cmd_low,
    "history": cmd_history,
    "receive": cmd_receive,
    "ship": cmd_ship,
    "quote": cmd_quote,
    "fulfil": cmd_fulfil,
    "invoice": cmd_invoice,
    "report": cmd_report,
}


# ---------------------------------------------------------------- entry point

def _error(message):
    try:
        sys.stderr.write("stockroom: %s\n" % message)
        sys.stderr.flush()
    except (OSError, ValueError):
        pass


def _write_stdout(text):
    try:
        out = sys.stdout.buffer
    except AttributeError:  # replaced by a text-only stream (e.g. in tests)
        sys.stdout.write(text)
        sys.stdout.flush()
        return
    sys.stdout.flush()
    out.write(text.encode("utf-8"))
    out.flush()


def run(argv):
    try:
        directory, command, args, opts = parse_command_line(argv)
    except UsageError as exc:
        _error(str(exc))
        try:
            sys.stderr.write(USAGE)
        except (OSError, ValueError):
            pass
        return 2
    try:
        data = Data(directory, FILES[command])
        output = HANDLERS[command](data, args, opts)
    except ReadError as exc:
        _error(str(exc))
        return 2
    except Refused as exc:
        _error(str(exc))
        return 1
    try:
        _write_stdout(output)
    except BrokenPipeError:
        try:
            devnull = os.open(os.devnull, os.O_WRONLY)
            os.dup2(devnull, sys.stdout.fileno())
        except (OSError, ValueError, AttributeError):
            pass
    return 0


def main(argv=None):
    return run(sys.argv[1:] if argv is None else list(argv))


if __name__ == "__main__":
    sys.exit(main())
